SELECT ti.techkey, ti.vpnratio, ti.proxycount, ti.ipcountrynum, 
       ROUND(CAST(0.4 * ti.vpnratio + 0.3 * (ti.proxycount::numeric / 10) + 0.3 * (ti.ipcountrynum::numeric / 20)) AS numeric(10,6)) as tei
FROM technicalinfo ti LIMIT 5;

SELECT ti.techkey, ti.vpnratio, ti.proxycount, ti.ipcountrynum, 
       ROUND(CAST((0.4 * ti.vpnratio + 0.3 * (ti.proxycount::numeric / 10) + 0.3 * (ti.ipcountrynum::numeric / 20)) AS numeric), 6) as tei
FROM technicalinfo ti LIMIT 5;

SELECT COUNT(*) FROM account a 
JOIN profile p ON a.accindex = p.profaccref 
JOIN sessionbehavior sb ON p.profkey = sb.sessprofref;
